package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.HistoryService;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /** A grade's rate as the screen shows it: the percent always with two decimals, and its
     *  from-date (null when it applies from the beginning of time) and to-date (null: for good). */
    public record RateView(String grade, LocalDate from, LocalDate to, String pct) {
        static RateView of(Rate r) {
            return new RateView(r.getGrade(), r.getFrom(), r.getTo(), r.getPct().setScale(2).toPlainString());
        }
    }

    /** A rate as the form submits it: a percent of 0.00 or more with up to two decimals, and an
     *  optional from-date (absent: from the beginning of time) and to-date (absent: for good), not
     *  before the from-date. */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct, LocalDate from, LocalDate to) {
        @AssertTrue(message = "to-date before from-date")
        public boolean isToNotBeforeFrom() {
            return from == null || to == null || !to.isBefore(from);
        }
    }

    private final RateService service;
    private final HistoryService history;

    public RateController(RateService service, HistoryService history) {
        this.service = service;
        this.history = history;
    }

    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        List<Rate> rates = asOf == null ? service.list(sheetId) : history.asOf(sheetId, asOf).rates();
        return rates.stream().map(RateView::of).toList();
    }

    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RateForm body) {
        return RateView.of(service.set(sheetId, user.trim(), grade, body.from(), body.to(), new BigDecimal(body.pct())));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.history.HistoryListener;

/** One of the sheet's rates for a grade: a percent with two decimals, in force from its from-date
 *  (from the beginning of time when it has none) through its to-date (for good when it has none). */
@Entity
@EntityListeners(HistoryListener.class)
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.to = to;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    /** The first date the rate is in force; null when it applies from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    /** Whether the rate is in force on a date (it may be overtaken by a later one). */
    public boolean appliesOn(LocalDate date) {
        return from == null || !from.isAfter(date);
    }

    /** The last date the rate applies; null when it applies for good. */
    public LocalDate getTo() {
        return to;
    }

    public void setTo(LocalDate to) {
        this.to = to;
    }

    /** Whether the rate still applies on a date it is in force (not past its to-date). */
    public boolean runsThrough(LocalDate date) {
        return to == null || !to.isBefore(date);
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates, by grade. */
    List<Rate> findBySheetIdOrderByGradeAsc(String sheetId);

    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** The grade's rate for a from-date (null: the undated rate). */
    default Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate from) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> Objects.equals(r.getFrom(), from))
                .findFirst();
    }

    /** The grade's rate in force on a date: the one with the latest from-date on or before it
     *  (an undated rate applying from the beginning of time); none when no rate applies yet, or when
     *  that one's to-date has passed by then. */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate on) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> r.appliesOn(on))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.runsThrough(on));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, RollupService rollup, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAsc(sheetId);
    }

    /** Set a grade's rate from a date (null: from the beginning of time) through a date (null: for
     *  good) on the sheet, replacing the rate it had for that from-date (the sheet is created first if it was never loaded). */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        sheets.load(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal scaled = pct.setScale(2);
        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from).orElse(null);
        try {
            if (rate == null) {
                rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, scaled));
            } else {
                rate.setPct(scaled);
                rate.setTo(to);
                rates.flush();
            }
        } catch (DataIntegrityViolationException e) {
            // set by another user at the same moment
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Rate changed at the same moment");
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + grade + " rate=" + scaled.toPlainString() + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));
        rollup.recordChanges(sheetId, user, before);
        return rate;
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';
import { Claim, cents, isBound, isCorrection, lateFrom, overdue, plusDays } from '../claims/claims-api';

export { plusDays };

/** A percent of 0.00 or more with up to two decimals. */
export const PCT_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

export interface Rate {
  grade: string;
  /** The first date (yyyy-mm-dd) the rate is in force; null when it applies from the beginning of time. */
  from: string | null;
  /** The last date (yyyy-mm-dd) the rate applies; null when it applies for good. */
  to: string | null;
  /** Always with two decimals, as the server formats it. */
  pct: string;
}

/** Of one grade's rates, the one in force on a date (yyyy-mm-dd): the one with the latest from-date
 *  on or before it, an undated rate applying from the beginning of time; null when none applies yet,
 *  or when that one's to-date has passed by then. */
export function pctOn(rates: readonly Rate[], date: string | null): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.from !== null && (date === null || r.from > date)) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  if (best?.to != null && date !== null && best.to < date) return null;
  return best?.pct ?? null;
}

// The sheet's rate for each grade, read and written through the server.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheetId), { headers: this.headers() }));
  }

  set(sheetId: string, grade: string, pct: string, from: string | null, to: string | null): Promise<Rate> {
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheetId)}/${encodeURIComponent(grade)}`, { pct, from, to }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function rateError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Choose a grade, enter a percent of 0.00 or more with up to two decimals and a from-date and to-date as yyyy-mm-dd or none, the to-date not before the from-date.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The rate was changed at the same moment; try again.';
  return otherError(e);
}

/** Whole cents times a percent (in hundredths of a percent), divided by 100, in whole cents,
 *  rounded half to even, or half up when `halfUp` (a negative product rounded as its size is).
 *  Worked in BigInt so large amounts stay exact. */
export function dueCents(cents: number, pctHundredths: number, halfUp = false): number {
  const product = BigInt(cents) * BigInt(pctHundredths);
  const size = product < 0n ? -product : product;
  const whole = size / 10000n;
  const rest = size % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
  return Number(product < 0n ? -rounded : rounded);
}

/** What a claim's late charge follows: the sheet's today and the late percent in force on each boundary date. */
export interface Lateness {
  today: string | null;
  /** The late percent with two decimals in force on a date. */
  latePctOn: (date: string) => string;
  /** The grace days a claim has (those of its person's grade in force on its date); none when left out. */
  graceOf?: (c: Claim) => number;
}

/** A claim's due in cents: the due fixed when it was settled, else the greater of the sheet's floor in
 *  force on its date and its figure (the rate figure a statement bound it to (unless PENDING), else its
 *  amount times its grade's rate in force on its date, rounded half up when `halfUp` (the claim's rounding
 *  policy) else half to even) with its late charge, rounded the same way, on top (a correction is neither
 *  raised to the floor nor charged late); null (n/a) with no figure. */
export function claimDueCents(rates: readonly Rate[], c: Claim, floorCents: number, late: Lateness, halfUp: boolean): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  const figure = figureCents(rates, c, halfUp);
  if (figure === null) return null;
  const charged = figure + lateChargeCents(c, figure, late, halfUp);
  return isCorrection(c) ? charged : Math.max(charged, floorCents);
}

function figureCents(rates: readonly Rate[], c: Claim, halfUp: boolean): number | null {
  if (isBound(c)) return c.statedDue === null ? null : cents(c.statedDue);
  const pct = pctOn(rates, c.date);
  return pct === null ? null : dueCents(cents(c.amount), cents(pct), halfUp);
}

/** An overdue claim's late charge in cents: for every full 30 days past its due-by plus its grace days, the late percent
 *  in force on that boundary date (that date plus 30, 60, 90 ... days) of its figure plus the charges of the
 *  boundaries before it (compounding), each rounded by
 *  the claim's rounding policy, added up; 0 when it is not overdue. */
function lateChargeCents(c: Claim, figure: number, late: Lateness, halfUp: boolean): number {
  const grace = late.graceOf?.(c) ?? 0;
  if (late.today === null || isCorrection(c) || !overdue(c, late.today, grace)) return 0;
  const from = lateFrom(c, grace);
  const days = Math.round((Date.parse(late.today) - Date.parse(from)) / 86_400_000);
  let charge = 0;
  for (let step = 1; step <= Math.floor(days / 30); step++) {
    const pct = cents(late.latePctOn(plusDays(from, step * 30)));
    if (pct !== 0) charge += dueCents(figure + charge, pct, halfUp);
  }
  return charge;
}

import { Component, computed, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { GRADES } from '../people/people-api';
import { PCT_PATTERN, Rate, RatesApi, pctOn, rateError } from './rates-api';

// The rate in force on the sheet's today for each grade, every rate the sheet has for each grade by
// from-date, and the form that sets a grade's rate from a date, optionally through a date.
@Component({
  selector: 'app-rates',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Set rate">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" formControlName="pct" inputmode="decimal" autocomplete="off" />
        <label for="rate-form-from">From (blank: always)</label>
        <input id="rate-form-from" type="date" data-testid="rate-form-from" formControlName="from" />
        <label for="rate-form-to">To (blank: for good)</label>
        <input id="rate-form-to" type="date" data-testid="rate-form-to" formControlName="to" />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        @if (error(); as err) {
          <p role="alert" data-testid="rate-form-error">{{ err }}</p>
        }
      </form>
      <table data-testid="rates-current">
        <caption>In force today</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (g of grades; track g) {
            <tr>
              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">{{ currentOf(g) ?? 'n/a' }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="rates-list">
        <caption>All rates</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (r of sorted(); track r.grade + '-' + (r.from ?? 'start')) {
            <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
              <th scope="row" data-testid="rate-grade">{{ r.grade }}</th>
              <td data-testid="rate-from">{{ r.from ?? '' }}</td>
              <td data-testid="rate-to">{{ r.to ?? '' }}</td>
              <td data-testid="rate-pct">{{ r.pct }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Rates {
  private readonly session = inject(Session);
  private readonly api = inject(RatesApi);

  /** The sheet's rates, each for a grade from a from-date. */
  readonly rates = input.required<Rate[]>();
  /** The rates by grade, then from-date (an undated rate first). */
  protected readonly sorted = computed(() => [...this.rates()].sort((a, b) =>
    a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '')));
  /** A rate just set, for the sheet to take in. */
  readonly saved = output<Rate>();

  protected readonly grades = GRADES;
  protected readonly error = signal<string | null>(null);
  /** Whether a submit is waiting for its answer; a second submit meanwhile is ignored. */
  private submitting = false;

  protected readonly form = new FormGroup({
    grade: new FormControl<string>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
  }

  /** The grade's rate in force on the sheet's today, or null when it has none then. */
  protected currentOf(grade: string): string | null {
    return pctOn(this.rates().filter((r) => r.grade === grade), this.session.today());
  }

  protected async submit(): Promise<void> {
